//회사개요 저장 
scwin.fn_CheckForm_1 = function() {
    //alert(dts_SumInfo.Text);
    if (!$c.cp.isModified(dts_SumInfo)) {
        $c.win.alert("변경된 내역이 없습니다.");
        return false;
    }
    return true;
};
scwin.fn_save_1 = function() {
    var code = "";
    if (scwin.fn_CheckForm_1()) {
        var res = window.confirm("저장하시겠습니까?");
        if (res) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            /*ORG SRC: dts_SumInfo.UserStatus(1) = TB_JOB_UPDATE;*/
            X = TB_JOB_UPDATE;
            scwin.fn_trs_1();
        }
    }
};
scwin.fn_trs_1 = function() {
    trs_SumInfo.Action = $c.lc.fn_encodeNSession("/NewListedCompanyAnalysisManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=updateNewCorpInfo&For=NSI");
