//부모창의 그리드에서 클릭된 로우의 값을 가져온다.
scwin.fn_getParam = function() {
    var parentWin = $c.frame.path("../");
    var paramObj = parentWin.gParamObj;
    if (paramObj == undefined) return;

    //setObjectValue(txb_seq, paramObj[0]);		
    scwin.rep_isu_cd = paramObj[0];
    //= txb_seq.value;

    //상단 tab의 첫번째 tab인 회사개요 값들을 가져온다.
    var url = "/NewListedCompanyAnalysisManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=getNewCorpManagement&For=NSI&inputMessageId=NLCM_IN&outputMessageId=NLCM_OUT_NSI" + "&REP_ISU_SRT_CD=" + scwin.rep_isu_cd;
    dts_SumInfo.DataID = encodeURI(url);
    dts_SumInfo.reset();
};
scwin.dts_MngInfo_OnLoadCompleted = function(rowcount) {
    //dataSet 로딩 후 경영권 방어수단 도입여부 setting 한다.
    var gay_0 = dts_MngInfo.getCellData(1, "C0_GAY");
    var gay_1 = dts_MngInfo.getCellData(1, "C1_GAY");
    var gay_2 = dts_MngInfo.getCellData(1, "C2_GAY");
    var gay_3 = dts_MngInfo.getCellData(1, "C3_GAY");
    var gay_4 = dts_MngInfo.getCellData(1, "C4_GAY");
    var say_0 = dts_MngInfo.getCellData(1, "C0_SAY");
    var say_1 = dts_MngInfo.getCellData(1, "C1_SAY");
    var say_2 = dts_MngInfo.getCellData(1, "C2_SAY");
    var say_3 = dts_MngInfo.getCellData(1, "C3_SAY");
    var say_4 = dts_MngInfo.getCellData(1, "C4_SAY");
    var cvey_0 = dts_MngInfo.getCellData(1, "C0_CVEY");
    var cvey_1 = dts_MngInfo.getCellData(1, "C1_CVEY");
    var cvey_2 = dts_MngInfo.getCellData(1, "C2_CVEY");
    var cvey_3 = dts_MngInfo.getCellData(1, "C3_CVEY");
    var cvey_4 = dts_MngInfo.getCellData(1, "C4_CVEY");

    //세 조건 중 하나라도 yes 일 경우  경영권 방어수단 도입여부를 yes로 세팅 
    if (gay_0 == "1" || say_0 == "1" || cvey_0 == "1") {
        rd_mdy_2_0.setValue("1");
    } else {
        rd_mdy_2_0.setValue("2");
    }
    if (gay_1 == "1" || say_1 == "1" || cvey_1 == "1") {
        rd_mdy_2_1.setValue("1");
    } else {
        rd_mdy_2_1.setValue("2");
    }
    if (gay_2 == "1" || say_2 == "1" || cvey_2 == "1") {
        rd_mdy_2_2.setValue("1");
    } else {
        rd_mdy_2_2.setValue("2");
    }
    if (gay_3 == "1" || say_3 == "1" || cvey_3 == "1") {
        rd_mdy_2_3.setValue("1");
    } else {
        rd_mdy_2_3.setValue("2");
    }
    if (gay_4 == "1" || say_4 == "1" || cvey_4 == "1") {
        rd_mdy_2_4.setValue("1");
    } else {
        rd_mdy_2_4.setValue("2");
    }
};
scwin.dts_MngInfo_OnLoadError = function() {
    $c.stf.alert_error(dts_MngInfo);
};
scwin.dts_ValInfo_OnLoadCompleted = function(rowcount) {
    var isur_cd = dts_ValInfo.getCellData(1, "ISUR_CD");
    var ccnt_1 = (dts_ValInfo.getCellData(1, "C1_CPT_CHG_CNT") == "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C1_CPT_CHG_CNT")));
    var ccnt_2 = (dts_ValInfo.getCellData(1, "C2_CPT_CHG_CNT") == "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C2_CPT_CHG_CNT")));
    var ccnt_3 = (dts_ValInfo.getCellData(1, "C3_CPT_CHG_CNT") == "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C3_CPT_CHG_CNT")));
    var ccnt_4 = (dts_ValInfo.getCellData(1, "C4_CPT_CHG_CNT") == "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C4_CPT_CHG_CNT")));

    //자본금 변동회수가 0보다 클경우 변동 원인을 서버에 요청한다.
    if (ccnt_1 > 0) {
        scwin.fn_list_sync4_1(isur_cd, 1);
    }
    if (ccnt_2 > 0) {
        scwin.fn_list_sync4_2(isur_cd, 2);
    }
    if (ccnt_3 > 0) {
        scwin.fn_list_sync4_3(isur_cd, 3);
    }
    if (ccnt_4 > 0) {
        scwin.fn_list_sync4_4(isur_cd, 4);
    }

    //각 회차의 데이터 존재여부를 판단하기 위하여 각 회차의 주가 존재여부를 가져온다.
    var isExist_1 = (dts_ValInfo.getCellData(1, "C1_STKPRC") == "" ? false : true);
    var isExist_2 = (dts_ValInfo.getCellData(1, "C2_STKPRC") == "" ? false : true);
    var isExist_3 = (dts_ValInfo.getCellData(1, "C3_STKPRC") == "" ? false : true);
    var isExist_4 = (dts_ValInfo.getCellData(1, "C4_STKPRC") == "" ? false : true);

    //누적변동 횟수를 세팅한다.	
    var ccnt_a_1 = ccnt_1;
    var ccnt_a_2 = ccnt_1 + ccnt_2;
    var ccnt_a_3 = ccnt_1 + ccnt_2 + ccnt_3;
    var ccnt_a_4 = ccnt_1 + ccnt_2 + ccnt_3 + ccnt_4;
    $c.stf.setObjectValue(txb_chg_acnt_4_1, (isExist_1 ? (ccnt_a_1 == 0 ? "" : ccnt_a_1) : ""));
    $c.stf.setObjectValue(txb_chg_acnt_4_2, (isExist_2 ? (ccnt_a_2 == 0 ? "" : ccnt_a_2) : ""));
    $c.stf.setObjectValue(txb_chg_acnt_4_3, (isExist_3 ? (ccnt_a_3 == 0 ? "" : ccnt_a_3) : ""));
    $c.stf.setObjectValue(txb_chg_acnt_4_4, (isExist_4 ? (ccnt_a_4 == 0 ? "" : ccnt_a_4) : ""));

    //누적자본금을 세팅한다.
    var cp_amt_1 = (dts_ValInfo.getCellData(1, "C1_CPT_CHG_AMT") == "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C1_CPT_CHG_AMT")));
    var cp_amt_2 = (dts_ValInfo.getCellData(1, "C2_CPT_CHG_AMT") == "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C2_CPT_CHG_AMT")));
    var cp_amt_3 = (dts_ValInfo.getCellData(1, "C3_CPT_CHG_AMT") == "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C3_CPT_CHG_AMT")));
    var cp_amt_4 = (dts_ValInfo.getCellData(1, "C4_CPT_CHG_AMT") == "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C4_CPT_CHG_AMT")));
    var cp_amt_a_1 = cp_amt_1;
    var cp_amt_a_2 = cp_amt_1 + cp_amt_2;
    var cp_amt_a_3 = cp_amt_1 + cp_amt_2 + cp_amt_3;
    var cp_amt_a_4 = cp_amt_1 + cp_amt_2 + cp_amt_3 + cp_amt_4;
    txb_cpt_chg_ac_4_1.setValue(isExist_1 ? (cp_amt_a_1 == 0 ? "" : cp_amt_a_1) : "");
    txb_cpt_chg_ac_4_2.setValue(isExist_2 ? (cp_amt_a_2 == 0 ? "" : cp_amt_a_2) : "");
    txb_cpt_chg_ac_4_3.setValue(isExist_3 ? (cp_amt_a_3 == 0 ? "" : cp_amt_a_3) : "");
    txb_cpt_chg_ac_4_4.setValue(isExist_4 ? (cp_amt_a_4 == 0 ? "" : cp_amt_a_4) : "");
};
scwin.dts_ValInfo_OnLoadError = function() {
    $c.stf.alert_error(dts_ValInfo);
};
scwin.dts_ValCCRInfo_1_OnLoadCompleted = function(rowcount) {
    var rsn_list = "";
    for (var i = 1; i <= dts_ValCCRInfo_1.getTotalRow(); i++) {
        rsn_list += dts_ValCCRInfo_1.getCellData(i, "CD_VAL_NM") + ",";
    }
    if (rsn_list != "") {
        //마지막  ','  제거한다. 
        rsn_list = rsn_list.substr(0, (rsn_list.length - 1));
        $c.stf.setObjectValue(txb_chg_rsn_4_1, rsn_list);
    }
};
